package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/transactions/{transactionId}/tags") public class TransactionTagController{private final TransactionTagService service;public TransactionTagController(TransactionTagService s){service=s;}@PostMapping public Mono<TransactionTagView> add(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID transactionId,@Valid@RequestBody TagTransactionRequest r){return service.add(a,transactionId,r);}@GetMapping public Flux<TransactionTagView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID transactionId){return service.list(a,transactionId);}@DeleteMapping("/{tagId}")public Mono<Void> remove(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID transactionId,@PathVariable UUID tagId){return service.remove(a,transactionId,tagId);}}
